// Writes the secure send screen's words (src/sendScreenText.json, every app language) into Swift and
// Kotlin source, so both phones show exactly the same sentences. Run after editing the JSON:
//   node scripts/gen-send-screen-text.mjs
// test/sendSummary.test.ts fails when the generated files are out of date.
import { readFileSync, writeFileSync } from 'node:fs';

const text = JSON.parse(readFileSync(new URL('../src/sendScreenText.json', import.meta.url), 'utf8'));
const keys = Object.keys(text).sort();
const langs = [...new Set(keys.flatMap((k) => Object.keys(text[k])))].sort();
const lit = (s) => JSON.stringify(s); // JSON string literals are valid Swift and Kotlin strings here (no $ or \( in the texts)
for (const k of keys) for (const l of langs) if (/\$|\\\(/.test(text[k][l] ?? '')) throw new Error(`unsafe character in ${l}: ${k}`);

export function swift() {
  const rows = langs.map((l) => `    ${lit(l)}: [\n${keys.map((k) => `      ${lit(k)}: ${lit(text[k][l])},`).join('\n')}\n    ],`).join('\n');
  return `// Generated by scripts/gen-send-screen-text.mjs from src/sendScreenText.json. Do not edit.
enum SendScreenText {
  static let all: [String: [String: String]] = [
${rows}
  ]

  /// The sentence in \`lang\` (English when missing), with {placeholders} filled in.
  static func t(_ key: String, _ lang: String, _ vars: [String: String] = [:]) -> String {
    var s = all[lang]?[key] ?? all["en"]?[key] ?? key
    for (k, v) in vars { s = s.replacingOccurrences(of: "{\\(k)}", with: v) }
    return s
  }
}
`;
}

export function kotlin() {
  const rows = langs.map((l) => `    ${lit(l)} to mapOf(\n${keys.map((k) => `      ${lit(k)} to ${lit(text[k][l])},`).join('\n')}\n    ),`).join('\n');
  return `// Generated by scripts/gen-send-screen-text.mjs from src/sendScreenText.json. Do not edit.
package app.foxsafe.walletcore

object SendScreenText {
  val all: Map<String, Map<String, String>> = mapOf(
${rows}
  )

  /** The sentence in [lang] (English when missing), with {placeholders} filled in. */
  fun t(key: String, lang: String, vars: Map<String, String> = emptyMap()): String {
    var s = all[lang]?.get(key) ?: all["en"]?.get(key) ?: key
    for ((k, v) in vars) s = s.replace("{" + k + "}", v)
    return s
  }
}
`;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  writeFileSync(new URL('../ios/SendScreenText.swift', import.meta.url), swift());
  writeFileSync(new URL('../android/src/main/java/app/foxsafe/walletcore/SendScreenText.kt', import.meta.url), kotlin());
  console.log(`${keys.length} sentences x ${langs.length} languages written`);
}
